    /// Build strata from relation names and edges given as (goal, dependency)
    /// index pairs into the name list.
    fn strata_of(names: &[&str], edges: &[(usize, usize)]) -> Strata {
        let idents: Vec<Ident> = names.iter().map(|n| ident(n)).collect();
        let relations: HashSet<Ident> = idents.iter().cloned().collect();
        let deps: HashSet<(&Ident, &Ident)> = edges
