            .map(|&(a, b)| (&idents[a], &idents[b]))
            .collect();
        Strata::new(relations, deps)
    }

    fn flat(strata: &Strata) -> Vec<String> {
        strata
            .iter()
            .flat_map(|s| s.iter().map(|i| i.to_string()))
            .collect()
    }

    #[test]
    fn empty_program_has_no_strata() {
        let strata = strata_of(&[], &[]);
        assert_eq!(strata.iter().count(), 0);
    }

    #[test]
    fn single_relation_without_dependencies() {
        let strata = strata_of(&["A"], &[]);
        assert_eq!(flat(&strata), vec!["A".to_string()]);
        assert_eq!(strata.iter().count(), 1);
        assert_eq!(strata.find_relation(&ident("A")), 0);
    }

    #[test]
    fn isolated_relations_each_get_a_stratum() {
        let strata = strata_of(&["A", "B", "C"], &[]);
        assert_eq!(strata.iter().count(), 3);
        for stratum in strata.iter() {
            assert_eq!(stratum.len(), 1);
        }
        let mut names = flat(&strata);
        names.sort();
        assert_eq!(names, vec!["A", "B", "C"]);
